var eventStore []model.RealtimeEvent
var eventMu sync.Mutex
var eventCounter int64

func (s *Service) PublishEvent(eventType, entityType, entityID string, payload map[string]interface{}) {
	eventMu.Lock()
	defer eventMu.Unlock()
	eventCounter++
	evt := model.RealtimeEvent{
		ID:         eventCounter,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now(),
	}
	eventStore = append(eventStore, evt)
	if len(eventStore) > 1000 {
		eventStore = eventStore[len(eventStore)-500:]
	}
}

func (s *Service) GetEvents(since int64) []model.RealtimeEvent {
	eventMu.Lock()
	defer eventMu.Unlock()
	if since == 0 && len(eventStore) > 0 {
		since = eventStore[0].ID - 1
	}
	var result []model.RealtimeEvent
	for _, e := range eventStore {
		if e.ID > since {
			result = append(result, e)
		}
	}
	if result == nil {
		result = []model.RealtimeEvent{}
	}
	return result
}

