func (h *Handler) CreateSampleRequest(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}

	sampleID := uid()
	originLat, originLng := 0.0, 0.0
	if coord, ok := body["origin"].(map[string]interface{}); ok {
		originLat, _ = coord["latitude"].(float64)
		originLng, _ = coord["longitude"].(float64)
	}
	stID, _ := body["sampleTypeId"].(string)
	originType, _ := body["originType"].(string)
	originNodeID, _ := body["originNodeId"].(string)
	deadlineStr, _ := body["deliveryDeadline"].(string)
	earliestStr, _ := body["earliestCollectionAt"].(string)
	latestStr, _ := body["latestCollectionAt"].(string)

	deadline, _ := time.Parse(time.RFC3339, deadlineStr)
	if deadline.IsZero() {
		deadline = time.Now().Add(24 * time.Hour)
	}

	var earliest, latest sql.NullTime
	if t, err := time.Parse(time.RFC3339, earliestStr); err == nil {
		earliest = sql.NullTime{Time: t, Valid: true}
	}
	if t, err := time.Parse(time.RFC3339, latestStr); err == nil {
		latest = sql.NullTime{Time: t, Valid: true}
	}

	if originType == "" {
		originType = "node"
	}

	st, err := h.svc.GetSampleType(h.DB, stID)
	if err != nil {
		h.err(w, 400, "invalid sample type", "BAD_REQUEST")
		return
	}

	requestID := uid()

	// Set incompatible types
	var incompatibles []string
	for _, inc := range st.IncompatibleSampleTypes {
		incompatibles = append(incompatibles, inc)
	}

	_, err = h.DB.Exec(`INSERT INTO samples (sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, origin_node_id,
		requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		sample_type_id, container_type, temperature_min_c, temperature_max_c, status, sealed, serviceability, latitude, longitude)
		VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), $8, $9, $10, $11, $12, $13, $14, 'requested', FALSE, 'unchecked', $4, $5)`,
		sampleID, requestID, claims.UserID, originLat, originLng, originType, nullStr(originNodeID),
		deadline, earliest, latest,
		stID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC)

	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
		return
	}

	for _, inc := range incompatibles {
		h.DB.Exec(`INSERT INTO sample_incompatibilities (sample_id, incompatible_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, sampleID, inc)
	}

	h.svc.WriteAudit(h.DB, claims.UserID, "requester", "create_request", "sample", sampleID, true, body)

	// Return sample
	rows := h.DB.QueryRow(`SELECT s.sample_id, s.request_id, s.status, s.sample_type_id, s.origin_lat, s.origin_lng,
		s.delivery_deadline, s.earliest_collection_at, s.latest_collection_at, s.serviceability,
		s.origin_type, s.origin_node_id, s.container_type
		FROM samples s WHERE s.sample_id = $1`, sampleID)
	var sResp map[string]interface{}
	_ = rows
	sm, _ := h.svc.GetSampleLifecycle(h.DB, sampleID, claims.UserID)
	h.respond(w, 201, sm)
}

