	// Update assignment
	h.DB.Exec(`UPDATE assignments SET status='completed', updated_at=NOW() WHERE sample_id=$1 AND worker_id=$2 AND kind='collection' AND status='accepted'`, sampleID, claims.UserID)

	sm, _ := h.svc.GetSampleLifecycle(h.DB, sampleID, claims.UserID)
