// ── Register Pre-Sealed ──

func (h *Handler) RegisterPreSealedSample(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}

	sampleID := uid()
	stID, _ := body["sampleTypeId"].(string)
	originType, _ := body["originType"].(string)
	originNodeID, _ := body["originNodeId"].(string)
	deadlineStr, _ := body["deliveryDeadline"].(string)

	if originType == "" {
		originType = "node"
	}
	// Must not be home
	if originType == "home" {
		h.err(w, 400, "pre-sealed samples must originate from clinic or node", "BAD_REQUEST")
		return
	}

	deadline, _ := time.Parse(time.RFC3339, deadlineStr)
	if deadline.IsZero() {
		deadline = time.Now().Add(24 * time.Hour)
	}

	st, err := h.svc.GetSampleType(h.DB, stID)
	if err != nil {
		h.err(w, 400, "invalid sample type", "BAD_REQUEST")
		return
	}

	originLat, originLng := 0.0, 0.0
	if originNodeID != "" {
		h.DB.QueryRow(`SELECT latitude, longitude FROM locations WHERE location_id=$1`, originNodeID).Scan(&originLat, &originLng)
	}

	h.DB.Exec(`INSERT INTO samples (sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, origin_node_id,
		requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c,
		status, sealed, serviceability, current_holder_id, latitude, longitude)
		VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), $8, $9, $10, $11, $12, 'collected', TRUE, 'unchecked', $3, $4, $5)`,
		sampleID, uid(), claims.UserID, originLat, originLng, originType, nullStr(originNodeID),
		deadline, stID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC)

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "register_presealed", "sample", sampleID, true, body)
	sm, _ := h.svc.GetSampleLifecycle(h.DB, sampleID, claims.UserID)
	h.respond(w, 201, sm)
}

