func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	sampleID, _ := body["sampleId"].(string)
	containerType, _ := body["containerType"].(string)
	temperature, _ := body["temperature"].(float64)

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "handling_checkpoint", "sample", sampleID, true, map[string]interface{}{
		"containerType": containerType,
		"temperature":   temperature,
	})

	// Check against sample requirements
	var expectedContainer string
	var minT, maxT float64
	err = h.DB.QueryRow(`SELECT container_type, temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, sampleID).Scan(&expectedContainer, &minT, &maxT)
	if err == nil {
		inRange := temperature >= minT && temperature <= maxT
		containerOk := expectedContainer == "" || containerType == expectedContainer
		if !inRange || !containerOk {
			// Mark as exception
			reason := ""
			if !inRange {
				reason = fmt.Sprintf("temperature %.1f outside range [%.1f, %.1f]", temperature, minT, maxT)
			}
			if !containerOk {
				if reason != "" {
					reason += "; "
				}
				reason += fmt.Sprintf("container %s does not match required %s", containerType, expectedContainer)
			}
			h.DB.Exec(`UPDATE samples SET status='exception', exception_reason=$1, exception_observed_at=NOW(), exception_recorded_by=$2 WHERE sample_id=$3`,
				reason, claims.UserID, sampleID)
		}
	}

	sm, _ := h.svc.GetSampleLifecycle(h.DB, sampleID, claims.UserID)
	h.respond(w, 200, sm)
}

// ── Sample Lifecycle ──

func (s *Service) GetSampleLifecycle(database *sql.DB, sampleID, viewerID string) (map[string]interface{}, error) {
	var sm map[string]interface{}
	var originLat, originLng sql.NullFloat64
	var originNodeID, reqID, requesterID, status, stID, originType, serv string
	var curHolderID, journeyID, labID, recLabID, handoffID sql.NullString
	var reqAt, deadline, earliest, latest, locRec sql.NullTime
	var exceptionReason, exceptionRecordedBy sql.NullString
	var exceptionObserved sql.NullTime
	var sealed bool
	var containerType, tempMin, tempMax sql.NullString
	var lat, lng sql.NullFloat64

	err := database.QueryRow(`SELECT sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, origin_node_id,
		requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		sample_type_id, container_type, temperature_min_c, temperature_max_c,
		status, sealed, serviceability, current_holder_id, active_journey_id,
		target_laboratory_id, received_laboratory_id, pending_handoff_id,
		exception_reason, exception_observed_at, exception_recorded_by,
		latitude, longitude, location_recorded_at
		FROM samples WHERE sample_id=$1`, sampleID).Scan(
		&sampleID, &reqID, &requesterID, &originLat, &originLng, &originType, &originNodeID,
		&reqAt, &deadline, &earliest, &latest,
		&stID, &containerType, &tempMin, &tempMax,
		&status, &sealed, &serv, &curHolderID, &journeyID,
		&labID, &recLabID, &handoffID,
		&exceptionReason, &exceptionObserved, &exceptionRecordedBy,
		&lat, &lng, &locRec)

	if err != nil {
		return nil, err
	}

	sm = map[string]interface{}{
		"sampleId":       sampleID,
		"requestId":      reqID,
		"requesterId":    requesterID,
		"originType":     originType,
		"sampleTypeId":   stID,
		"status":         status,
		"sealed":         sealed,
		"serviceability": serv,
	}

	if originLat.Valid {
		sm["origin"] = map[string]float64{"latitude": originLat.Float64, "longitude": originLng.Float64}
	}
	if originNodeID.Valid {
		sm["originNodeId"] = originNodeID.String
	}
	if reqAt.Valid {
		sm["requestedAt"] = reqAt.Time
	}
	if deadline.Valid {
		sm["deliveryDeadline"] = deadline.Time
	}
	if earliest.Valid {
		sm["earliestCollectionAt"] = earliest.Time
	}
	if latest.Valid {
		sm["latestCollectionAt"] = latest.Time
	}
	if curHolderID.Valid {
		sm["currentHolderId"] = curHolderID.String
	}
	if journeyID.Valid {
		sm["activeJourneyId"] = journeyID.String
	}
	if labID.Valid {
		sm["targetLaboratoryId"] = labID.String
	}
	if recLabID.Valid {
		sm["receivedLaboratoryId"] = recLabID.String
	}
	if handoffID.Valid {
		sm["pendingHandoffId"] = handoffID.String
	}
	if exceptionReason.Valid {
		sm["exception"] = map[string]interface{}{
			"reason":     exceptionReason.String,
			"observedAt": exceptionObserved.Time,
			"recordedBy": exceptionRecordedBy.String,
		}
	}
	if lat.Valid {
		sm["latestLocation"] = map[string]float64{"latitude": lat.Float64, "longitude": lng.Float64}
	}
	if locRec.Valid {
		sm["locationRecordedAt"] = locRec.Time
		sm["locationStale"] = time.Since(locRec.Time) > 15*time.Minute
	} else {
		sm["locationStale"] = false
	}

	timeline, _ := s.GetTimeline(database, sampleID)
	sm["timeline"] = timeline

	return sm, nil
}

// ── Journey Plan ──

func (s *Service) GetJourneyPlan(database *sql.DB, journeyID, viewerID string, roles []string) (interface{}, error) {
	var jid, status, routeMode string
	var planVersion int
	var estDelivery sql.NullTime
	var totalCost sql.NullFloat64
	var parentJid sql.NullString

	err := database.QueryRow(`SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units
		FROM journeys WHERE journey_id=$1`, journeyID).Scan(&jid, &parentJid, &planVersion, &routeMode, &status, &estDelivery, &totalCost)
	if err != nil {
		return nil, err
	}

	// Get samples
	sRows, err := database.Query(`SELECT sample_id FROM journey_samples WHERE journey_id=$1`, journeyID)
	if err != nil {
		return nil, err
	}
	defer sRows.Close()
	var sampleIDs []string
	for sRows.Next() {
		var sid string
		sRows.Scan(&sid)
		sampleIDs = append(sampleIDs, sid)
	}

	// Get stops
	stRows, err := database.Query(`SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	defer stRows.Close()
	var stops []model.JourneyStop
	for stRows.Next() {
		var stop model.JourneyStop
		var completed sql.NullTime
		stRows.Scan(&stop.StopID, &stop.LocationID, &stop.StopType, &stop.Sequence, &stop.EstimatedAt, &stop.DwellMinutes, &stop.Coordinate.Latitude, &stop.Coordinate.Longitude, &completed)
		if completed.Valid {
			stop.CompletedAt = &completed.Time
		}
		stops = append(stops, stop)
	}

	// Get legs (assignments)
	lRows, err := database.Query(`SELECT assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id
		FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	defer lRows.Close()
	var legs []model.JourneyLeg
	var workerIDs []string
	for lRows.Next() {
		var leg model.JourneyLeg
		var from, to, worker, sample sql.NullString
		lRows.Scan(&leg.AssignmentID, &leg.Sequence, &leg.Status, &from, &to, &worker, &sample)
		if from.Valid {
			leg.FromLocationID = from.String
		}
		if to.Valid {
			leg.ToLocationID = to.String
		}
		if worker.Valid {
			leg.WorkerID = &worker.String
			workerIDs = append(workerIDs, worker.String)
		}
		if sample.Valid {
			leg.SampleID = &sample.String
		}
		legs = append(legs, leg)
	}

	// Determine if viewer is a worker
	isWorker := false
	for _, r := range roles {
		if r == "collection_professional" || r == "delivery_partner" || r == "node_handler" || r == "laboratory_team" {
			isWorker = true
			break
		}
	}
	isRequester := false
	for _, r := range roles {
		if r == "requester" {
			isRequester = true
			break
		}
	}

	jp := map[string]interface{}{
		"journeyId":   jid,
		"planVersion": planVersion,
		"routeMode":   routeMode,
		"status":      status,
		"sampleIds":   sampleIDs,
	}

	if parentJid.Valid {
		jp["parentJourneyId"] = parentJid.String
	}
	if estDelivery.Valid {
		jp["estimatedDeliveryAt"] = estDelivery.Time
	}
	if totalCost.Valid {
		jp["totalCostUnits"] = totalCost.Float64
	}

	if isWorker {
		jp["orderedStops"] = stops
		jp["legs"] = legs
		jp["assignedWorkerIds"] = workerIDs
	} else if isRequester {
		jp["orderedStops"] = stops
		// Simplified legs for requester
		var simpleLegs []map[string]string
		for _, l := range legs {
			simpleLegs = append(simpleLegs, map[string]string{
				"assignmentId": l.AssignmentID,
				"status":       l.Status,
				"fromLocationId": l.FromLocationID,
				"toLocationId":   l.ToLocationID,
			})
		}
		jp["legs"] = simpleLegs
	} else {
		jp["orderedStops"] = stops
		jp["legs"] = legs
		jp["assignedWorkerIds"] = workerIDs
	}

	return jp, nil
}

