		if msg == "handoff already completed" {
			code = 409
		}
		h.err(w, code, msg, "ERROR")
		return
	}
	h.audit(r, "confirm_handoff", "handoff", fmt.Sprintf("%v", body["handoffId"]), true, body)
	h.respond(w, 200, result)
}

