func (h *Handler) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	locID, _ := body["locationId"].(string)
	fn, _ := body["function"].(string)
	fnActive, _ := body["active"].(bool)
	if locID == "" || fn == "" {
		h.fail(w, 400, "locationId and function required", "invalid_json")
		return
	}
	if !validLocationFunctions[fn] {
		h.fail(w, 400, "invalid location function", "invalid_location_function")
		return
	}
	if err := h.svc.SetLocationFunction(h.DB, locID, fn, fnActive); err != nil {
		if strings.Contains(err.Error(), "not found") {
			h.fail(w, 404, "location not found", "not_found")
		} else {
			h.fail(w, 500, err.Error(), "internal_error")
		}
		return
	}
	loc, _ := h.svc.GetLocation(h.DB, locID)
	functions := map[string]bool{
		"collection_point": false,
		"transfer_point":   false,
		"hub":              false,
		"laboratory":       false,
	}
	if loc != nil {
		functions["collection_point"] = loc.Functions.CollectionPoint
		functions["transfer_point"] = loc.Functions.TransferPoint
		functions["hub"] = loc.Functions.Hub
		functions["laboratory"] = loc.Functions.Laboratory
	}
	h.ok(w, 200, map[string]interface{}{
		"locationId": locID,
		"function":   fn,
		"active":     fnActive,
		"functions":  functions,
	})
}"}

