	sampleID, _ := body["sampleId"].(string)
	if sampleID == "" {
		return nil, fmt.Errorf("sampleId required")
	}

	// Verify sample exists and is in a collectable state
	var status string
	err := database.QueryRow(`SELECT status FROM samples WHERE sample_id=$1`, sampleID).Scan(&status)
	if err != nil {
		return nil, fmt.Errorf("sample not found")
	}
	if status != "requested" && status != "assigned" {
		return nil, fmt.Errorf("sample is not ready for collection: %s", status)
	}

	// Verify assignment exists
	assignmentID, _ := body["assignmentId"].(string)
	var assignStatus, assignKind string
	err = database.QueryRow(`SELECT status, kind FROM assignments WHERE assignment_id=$1 AND worker_id=$2 AND sample_id=$3`,
		assignmentID, workerID, sampleID).Scan(&assignStatus, &assignKind)
	if err != nil {
		return nil, fmt.Errorf("assignment not found or not assigned to this worker")
	}
	if assignStatus != "accepted" {
		return nil, fmt.Errorf("assignment not in accepted state")
	}

	containerType, _ := body["containerType"].(string)
	observedTemp, _ := body["observedTemperatureC"].(float64)

	// Check handling compliance
	handlingCompliant := true
	st, err := s.GetSampleType(database, "")
	if err == nil && st != nil {
		if st.ContainerType != "" && st.ContainerType != containerType {
			handlingCompliant = false
		}
		if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
			handlingCompliant = false
		}
	}

	// Also get st from sample
	var stID string
	database.QueryRow(`SELECT sample_type_id FROM samples WHERE sample_id=$1`, sampleID).Scan(&stID)
	if stID != "" {
		st, _ = s.GetSampleType(database, stID)
		if st != nil {
			if st.ContainerType != "" && st.ContainerType != containerType {
				handlingCompliant = false
			}
			if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
				handlingCompliant = false
			}
		}
	}

	collectedAt, _ := body["collectedAt"].(string)
	sealedAt := time.Now()
	if t, err := time.Parse(time.RFC3339, collectedAt); err == nil {
		sealedAt = t
	}

	database.Exec(`UPDATE samples SET status='sealed', sealed=TRUE, current_holder_id=$1, updated_at=$2 WHERE sample_id=$3`, workerID, sealedAt, sampleID)
	database.Exec(`UPDATE assignments SET status='completed', updated_at=$2 WHERE assignment_id=$1`, assignmentID, sealedAt)

	if !handlingCompliant {
		database.Exec(`UPDATE samples SET exception_reason='handling_noncompliant', exception_observed_at=$1, exception_recorded_by=$2 WHERE sample_id=$3`, sealedAt, workerID, sampleID)
	}

	return map[string]interface{}{
