}", "new_str": "func (s *Service) MergeJourneys(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
	tid, _ := body["targetJourneyId"].(string)
	sidz, _ := body["sourceJourneyIds"].([]interface{})
	if tid == "" {
		return nil, fmt.Errorf("journeyId required")
	}
	ids := []string{}
	for _, x := range sidz {
		if s, ok := x.(string); ok {
			ids = append(ids, s)
		}
	}

	// Verify target journey exists
	var jStatus string
	var planVersion int
	var routeMode string
	err := db_.QueryRow(`SELECT status, plan_version, route_mode FROM journeys WHERE journey_id=$1`, tid).Scan(&jStatus, &planVersion, &routeMode)
	if err != nil {
		return nil, fmt.Errorf("target journey not found: %s", tid)
	}

	// Merge source sample IDs into target journey
	for _, sid := range ids {
		db_.Exec(`INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, tid, sid)
		db_.Exec(`UPDATE samples SET active_journey_id=$1 WHERE sample_id=$2 AND active_journey_id IS NULL`, tid, sid)
	}
	db_.Exec(`UPDATE journeys SET updated_at=NOW(), plan_version=plan_version+1 WHERE journey_id=$1`, tid)

	// Get sample IDs for the target journey
	sampleRows, _ := db_.Query(`SELECT sample_id FROM journey_samples WHERE journey_id=$1`, tid)
	var allSamples []string
	if sampleRows != nil {
		defer sampleRows.Close()
		for sampleRows.Next() {
			var sid string
			sampleRows.Scan(&sid)
			allSamples = append(allSamples, sid)
		}
	}
	if allSamples == nil {
		allSamples = []string{}
	}

	// Build JourneyStop list
	stopRows, _ := db_.Query(`SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, tid)
	var stops []map[string]interface{}
	if stopRows != nil {
		defer stopRows.Close()
		for stopRows.Next() {
			var stopID, locID, stopType string
			var seq, dwell int
			var lat, lng float64
			var estAt, compAt sql.NullTime
			stopRows.Scan(&stopID, &locID, &stopType, &seq, &estAt, &dwell, &lat, &lng, &compAt)
			st := map[string]interface{}{
				"stopId":     stopID,
				"locationId": locID,
				"stopType":   stopType,
				"sequence":   seq,
			}
			if estAt.Valid {
				st["estimatedAt"] = estAt.Time.Format(time.RFC3339)
			}
			if compAt.Valid {
				st["completedAt"] = compAt.Time.Format(time.RFC3339)
			}
			stops = append(stops, st)
		}
	}
	if stops == nil {
		stops = []map[string]interface{}{}
	}

	s.PublishEvent("merge", "journey", tid, map[string]interface{}{"sourceJourneyIds": ids})

	return map[string]interface{}{
		"journeyId":          tid,
		"planVersion":        planVersion + 1,
		"routeMode":          routeMode,
		"status":             jStatus,
		"sampleIds":          allSamples,
		"orderedStops":       stops,
		"legs":               []interface{}{},
		"assignedWorkerIds":  []string{},
		"valid":              true,
	}, nil
}"}

